package com.example.project.entity;

public class Project {
    private Long id;
    private String name;
    private String description;
    private String status;
    private String owner;
    private String createdAt;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
    public String getOwner() { return owner; }
    public void setOwner(String owner) { this.owner = owner; }
    public String getCreatedAt() { return createdAt; }
    public void setCreatedAt(String createdAt) { this.createdAt = createdAt; }
}

package com.example.project.dao;

import com.example.project.entity.Project;
import org.apache.ibatis.annotations.*;
import java.util.List;

@Mapper
public interface ProjectDao {

    @Select("SELECT * FROM projects ORDER BY created_at DESC")
    List<Project> findAll();

    // SQL拼接导致注入风险
    @Select("SELECT * FROM projects WHERE name LIKE '%${keyword}%'")
    List<Project> searchByName(@Param("keyword") String keyword);

    @Insert("INSERT INTO projects(name, description, status, owner, created_at) " +
            "VALUES(#{name}, #{description}, #{status}, #{owner}, #{createdAt})")
    void insert(Project project);

    @Delete("DELETE FROM projects WHERE id = #{id}")
    void deleteById(@Param("id") Long id);

    @Select("SELECT COUNT(*) FROM tasks WHERE project_id = #{projectId}")
    int countTasksByProjectId(@Param("projectId") Long projectId);

    @Select("SELECT COUNT(*) FROM project_members WHERE project_id = #{projectId}")
    int countMembersByProjectId(@Param("projectId") Long projectId);

    @Update("UPDATE projects SET status = #{status} WHERE id = #{id}")
    void updateStatus(@Param("id") Long id, @Param("status") String status);
}

package com.example.project.controller;

import com.example.project.entity.Project;
import com.example.project.service.ProjectService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;
import java.util.*;

@RestController
@RequestMapping("/api/projects")
public class ProjectController {

    @Autowired
    private ProjectService projectService;

    // 查询所有项目 - 无分页
    @GetMapping
    public Map<String, Object> listAll() {
        List<Project> projects = projectService.findAll();
        Map<String, Object> result = new HashMap<>();
        result.put("code", 0);
        result.put("data", projects);
        return result;
    }

    // 按名称模糊搜索 - SQL注入风险
    @GetMapping("/search")
    public Map<String, Object> search(@RequestParam String keyword) {
        List<Project> projects = projectService.searchByName(keyword);
        Map<String, Object> result = new HashMap<>();
        result.put("code", 0);
        result.put("data", projects);
        return result;
    }

    // 创建项目 - 无入参校验
    @PostMapping
    public Map<String, Object> create(@RequestBody Project project) {
        projectService.create(project);
        Map<String, Object> result = new HashMap<>();
        result.put("code", 0);
        result.put("msg", "创建成功");
        return result;
    }

    // 删除项目 - 无权限控制
    @DeleteMapping("/{id}")
    public Map<String, Object> delete(@PathVariable Long id) {
        projectService.deleteById(id);
        Map<String, Object> result = new HashMap<>();
        result.put("code", 0);
        result.put("msg", "删除成功");
        return result;
    }

    // 批量导入 - 循环中逐条插入
    @PostMapping("/batch-import")
    public Map<String, Object> batchImport(@RequestBody List<Project> projects) {
        int success = 0;
        int fail = 0;
        for (Project p : projects) {
            try {
                projectService.create(p);
                success++;
            } catch (Exception e) {
                fail++;
                System.out.println("导入失败: " + e.getMessage());
            }
        }
        Map<String, Object> result = new HashMap<>();
        result.put("code", 0);
        result.put("success", success);
        result.put("fail", fail);
        return result;
    }

    // 获取项目统计 - N+1查询
    @GetMapping("/stats")
    public Map<String, Object> getStats() {
        List<Project> projects = projectService.findAll();
        List<Map<String, Object>> stats = new ArrayList<>();
        for (Project p : projects) {
            Map<String, Object> stat = new HashMap<>();
            stat.put("project", p.getName());
            stat.put("taskCount", projectService.countTasksByProjectId(p.getId()));
            stat.put("memberCount", projectService.countMembersByProjectId(p.getId()));
            stats.add(stat);
        }
        Map<String, Object> result = new HashMap<>();
        result.put("code", 0);
        result.put("data", stats);
        return result;
    }
}

package com.example.project.service;

import com.example.project.dao.ProjectDao;
import com.example.project.entity.Project;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import java.util.*;
import java.text.SimpleDateFormat;

@Service
public class ProjectService {

    @Autowired
    private ProjectDao projectDao;

    // 线程不安全的 SimpleDateFormat 作为成员变量
    private SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

    public List<Project> findAll() {
        return projectDao.findAll();
    }

    // SQL拼接 - 注入风险
    public List<Project> searchByName(String keyword) {
        return projectDao.searchByName(keyword);
    }

    public void create(Project project) {
        project.setCreatedAt(sdf.format(new Date()));
        projectDao.insert(project);
    }

    public void deleteById(Long id) {
        projectDao.deleteById(id);
    }

    public int countTasksByProjectId(Long projectId) {
        return projectDao.countTasksByProjectId(projectId);
    }

    public int countMembersByProjectId(Long projectId) {
        return projectDao.countMembersByProjectId(projectId);
    }

    // 批量更新状态 - 无事务注解
    public void batchUpdateStatus(List<Long> ids, String status) {
        for (Long id : ids) {
            projectDao.updateStatus(id, status);
        }
    }

    // 导出数据 - 密钥硬编码
